[CmdletBinding()]param([string]$Root=(Get-Location).Path)
$ErrorActionPreference='Stop';$base=Join-Path $Root 'ES/Automation/WebPageStudio';$cross=Join-Path $base 'fixtures/network-receipt.cross-task.json';$raw=& (Join-Path $base 'Invoke-ESWebUiEvidenceAggregate.ps1') -TaskId 'expected-task' -NetworkReceiptPath $cross|ConvertFrom-Json;if($raw.decision -ne 'blocked' -or $raw.layers[0].findings -notcontains 'RECEIPT_TASK_MISMATCH'){throw 'CROSS_TASK_RECEIPT_ACCEPTED'}
$valid=(Join-Path $base 'fixtures/network-receipt.valid.json');$agg=& (Join-Path $base 'Invoke-ESWebUiEvidenceAggregate.ps1') -TaskId 'expected-task' -NetworkReceiptPath $valid|ConvertFrom-Json;$agg.layers[0].receiptHash='f'*64;$tmp=[IO.Path]::GetTempFileName();try{[IO.File]::WriteAllText($tmp,($agg|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false));try{& (Join-Path $base 'Convert-ESWebUiAggregateToABCD.ps1') -AggregatePath $tmp|Out-Null;throw 'STALE_HASH_ACCEPTED'}catch{if($_.Exception.Message -notlike '*RECEIPT_HASH_DRIFT*'){throw}}}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue};[ordered]@{validator='web-ui-receipt-identity-fixtures';status='passed';crossTask='blocked';staleHash='blocked';runtimeStatus='runtime-not-run';nonClaims=@('identity-fixtures-static','no-runtime-executed')}|ConvertTo-Json -Depth 8
